<?php
declare(strict_types=1);require __DIR__.'/bootstrap.php';require_admin();require_csrf();$id=(int)($_POST['record_id']??0);$deleted=json_decode((string)($_POST['deleted']??'[]'),true);$added=json_decode((string)($_POST['added']??'[]'),true);if(!is_array($deleted)||!is_array($added)||count($added)>1000||count($deleted)>10000)json_out(['success'=>false,'error'=>'補正データが正しくありません。'],422);$st=db()->prepare('SELECT object_number FROM seed_morphology_objects WHERE record_id=?');$st->execute([$id]);$valid=array_map('intval',$st->fetchAll(PDO::FETCH_COLUMN));if(!$valid){$check=db()->prepare('SELECT id FROM seed_count_records WHERE id=?');$check->execute([$id]);if(!$check->fetchColumn())json_out(['success'=>false,'error'=>'記録がありません。'],404);}$deleted=array_values(array_unique(array_map('intval',$deleted)));foreach($deleted as$n)if(!in_array($n,$valid,true))json_out(['success'=>false,'error'=>'削除対象に存在しない粒番号があります。'],422);$clean=[];foreach($added as$p){if(!is_array($p))continue;$x=(float)($p['x']??-1);$y=(float)($p['y']??-1);if($x>=0&&$x<=1&&$y>=0&&$y<=1)$clean[]=['x'=>round($x,6),'y'=>round($y,6)];}$auto=count($valid);$corrected=max(0,$auto-count($deleted)+count($clean));try{$pdo=db();$pdo->beginTransaction();$ins=$pdo->prepare('INSERT INTO seed_manual_corrections(record_id,automatic_count,corrected_count,deleted_object_ids,added_points,note,created_at) VALUES(?,?,?,?,?,?,NOW())');$ins->execute([$id,$auto,$corrected,json_encode($deleted),json_encode($clean),mb_substr(trim((string)($_POST['note']??'')),0,255)]);$up=$pdo->prepare('UPDATE seed_count_records SET seed_count=?,updated_at=NOW() WHERE id=?');$up->execute([$corrected,$id]);$pdo->commit();json_out(['success'=>true,'corrected_count'=>$corrected,'detail_url'=>'detail.php?id='.$id]);}catch(Throwable$e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();json_out(['success'=>false,'error'=>$e->getMessage()],500);}
